class Solution:
    def mergeArrays(self, nums1: list[list[int]], nums2: list[list[int]]) -> list[list[int]]:
        i, j = 0, 0
        n, m = len(nums1), len(nums2)
        res = []
        while i < n and j < m:
            id1, val1 = nums1[i]
            id2, val2 = nums2[j]
            if id1 == id2:
                res.append([id1, val1 + val2])
                i += 1
                j += 1
            elif id1 < id2:
                res.append([id1, val1])
                i += 1
            else:
                res.append([id2, val2])
                j += 1
        while i < n:
            res.append(nums1[i])
            i += 1
        while j < m:
            res.append(nums2[j])
            j += 1
        return res

class Solution {
public:
    std::vector<std::vector<int>> mergeArrays(std::vector<std::vector<int>>& nums1, std::vector<std::vector<int>>& nums2) {
        std::vector<std::vector<int>> res;
        int i = 0, j = 0;
        int n = nums1.size(), m = nums2.size();
        while (i < n && j < m) {
            if (nums1[i][0] == nums2[j][0]) {
                res.push_back({nums1[i][0], nums1[i][1] + nums2[j][1]});
                i++;
                j++;
            } else if (nums1[i][0] < nums2[j][0]) {
                res.push_back(nums1[i++]);
            } else {
                res.push_back(nums2[j++]);
            }
        }
        while (i < n) res.push_back(nums1[i++]);
        while (j < m) res.push_back(nums2[j++]);
        return res;
    }
};

class Solution {
    public int[][] mergeArrays(int[][] nums1, int[][] nums2) {
        java.util.List<int[]> res = new java.util.ArrayList<>();
        int i = 0, j = 0;
        int n = nums1.length, m = nums2.length;
        while (i < n && j < m) {
            if (nums1[i][0] == nums2[j][0]) {
                res.add(new int[]{nums1[i][0], nums1[i][1] + nums2[j][1]});
                i++;
                j++;
            } else if (nums1[i][0] < nums2[j][0]) {
                res.add(nums1[i++]);
            } else {
                res.add(nums2[j++]);
            }
        }
        while (i < n) res.add(nums1[i++]);
        while (j < m) res.add(nums2[j++]);
        return res.toArray(new int[res.size()][]);
    }
}

